  "parts": [
   {
    "label": "(a)",
    "marks": 6,
    "model": "Physical activity: Soccer.\nAnkle sprain: The ligaments are overstretched when the foot rolls over, causing pain, swelling and difficulty putting weight on the foot. Treat it with PRICE: protect the joint by stopping play, rest it, apply ice wrapped in a cloth for 15 to 20 minutes, compress it with an elastic bandage and elevate it above the heart.\nCut to the knee: A graze or cut after a fall or a tackle that causes bleeding. Wear gloves and apply direct pressure with a sterile dressing until the bleeding stops, then clean the wound with saline and cover it with a dry dressing.",
    "model_source": "sonnet-fix",
    "answerStatus": "written",
    "type": [
     "short-answer"
    ],
    "diagramRelation": "none",
    "offSpec": false,
    "notesRefs": [
     "pe-structures-strategies-roles-conventions-s3"
    ]
   },
   {
    "label": "(b)(i)",
    "marks": 4,
    "model": "Raise: Jog gently for about five minutes to raise heart rate, muscle temperature and blood flow to the working muscles.\nActivate: Switch on the muscles the sport relies on, such as the glutes, hamstrings and shoulders.\nMobilise: Move the joints through the ranges the sport uses, using leg swings, lunges with rotation and arm circles.\nPotentiate: Do progressively faster sport-specific efforts, building to strides and sprints so the body is ready at competition intensity.",
    "model_source": "haiku",
    "answerStatus": "written",
    "type": [
     "short-answer"
    ],
    "diagramRelation": "none",
    "offSpec": false,
    "notesRefs": [
     "pe-structures-strategies-roles-conventions-s3"
    ]
   },
   {
    "label": "(b)(ii)",
    "marks": 4,
    "model": "Gradual return to rest: Light activity keeps blood flowing back to the heart, which stops blood pooling and dizziness and helps clear waste products from the muscles.\nRecovery: Gentle stretching restores muscle length and range of movement, and the cool-down lets the athlete settle and prepare for the next session.",
    "model_source": "haiku",
    "answerStatus": "written",
    "type": [
     "short-answer"
    ],
    "diagramRelation": "none",
    "offSpec": false,
    "notesRefs": [
     "pe-structures-strategies-roles-conventions-s3"
    ]
   },
   {
    "label": "(c)(i)",
    "marks": 5,
    "model": "Adapted physical activity is the practice of changing activities, equipment, rules or teaching so that people with a disability or other individual need can take part meaningfully.\nIt is based on inclusion, so the activity is adjusted to suit the participant rather than the participant being excluded for not suiting the activity.\nFor example, a visually impaired player can use a bell ball in a game of football.",
    "model_source": "haiku",
    "answerStatus": "written",
    "type": [
     "short-answer"
    ],
    "diagramRelation": "none",
    "offSpec": true,
    "notesRefs": [
     "pe-promoting-physical-activity-s2"
    ]
   },
   {
    "label": "(c)(ii)",
    "marks": 9,
    "model": "Adapted equipment: Buy bell balls, sitting volleyball nets and sports wheelchairs so that inclusive versions of existing units can be taught without separate provision.\nExternal expertise: Invite disability sports bodies to run staff training and pupil workshops, which builds teacher confidence and normalises adapted activity for the whole year group.\nTimetabling: Build adapted activity into the timetable and existing PE units, so every pupil can take part in the same lessons with suitable modifications.",
    "model_source": "haiku",
    "answerStatus": "written",
    "type": [
     "short-answer"
    ],
    "diagramRelation": "none",
    "offSpec": true,
    "notesRefs": [
     "pe-promoting-physical-activity-s3"
    ]
   },
   {
    "label": "(d)",
    "marks": 12,
    "model": "Physical activity: swimming, front crawl.\nFirst law, inertia: A swimmer on the blocks stays at rest until the legs apply a force; once moving, the swimmer keeps constant velocity unless drag slows them, so streamlining off the wall preserves speed.\nSecond law, F = ma: Acceleration is proportional to the force from the arm pull and kick, and inversely proportional to mass, so a stronger, more powerful pull gives a faster start and quicker acceleration.\nThird law, action and reaction: The hands push water backwards and the water pushes the swimmer forwards with an equal and opposite force, and the legs push off the wall or block to drive the swimmer forward.",
    "model_source": "sonnet-long",
    "answerStatus": "written",
    "type": [
     "long-answer"
    ],
    "diagramRelation": "none",
    "offSpec": false,
    "notesRefs": [
     "pe-learning-skill-technique-s2"
    ]
   }
  ]
